INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_q_sigil','Crimson Sigil');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_q_sigil','A red iron seal worn by the duelists of the Crimson Circle. Master Klingenhand, outside the Golden Lance in Ferdok, wants them all.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_q_ledger','Klingenhand''s Ledger');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_q_ledger','Seven names in a shaking hand:\nJorgo Fairwind, the Harbour Riposte: drinks where Ardo fell, in Ferdok harbour.\nIlgrim Ashblade: burned a chapel. Smells of ash, fond of ruins.\nFaelwen Duskarrow: an elf who hunts elves. Likes old trees and wet feet.\nSir Wolfhart the Oathbreaker: sold a castle gate. Keeps company with the dead.\nSabeth Lionsbane: an outcast Amazon. Hunts something with fangs, far from here.\nGrimbart Ironbeard: a banished dwarf. Guards something deep under the mountains.\nRavena Blutfeder, the Crimson Master: waits where fire meets stone. You will know it when you get there.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_q_page1','Codex Page I: Of Embers');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_q_page1','A scorched page in draconic script. Master Rakorium will want it.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_q_page2','Codex Page II: Of Ashes');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_q_page2','A scorched page in draconic script. Master Rakorium will want it.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_q_page3','Codex Page III: Of Bones');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_q_page3','A scorched page in draconic script. Master Rakorium will want it.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_q_page4','Codex Page IV: Of Dreams');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_q_page4','A scorched page in draconic script. Master Rakorium will want it.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_npc_cc_jorgo','Jorgo Fairwind, the Harbour Riposte');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('8c9527ff-0a6d-57e4-a877-2fc103b76f99','You have the look of someone counting the steps between us. Seven, by my count. I am Jorgo Fairwind, first blade of the Crimson Circle, and I never attack first.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('2cfa65eb-3ab9-5f03-821f-7a270fd047b7','Your Circle ends here. Draw.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('76973c18-9e6d-589e-803f-f0e0b669b49c','Then you will die second. En garde!');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('fa071253-7f39-521a-8ee2-76ba63298b5d','Not today.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('cae7739a-0482-5d3b-ae08-6a7884519505','Jorgo Fairwind');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('dfb65f0e-08fc-5560-8b1e-a735be001f5e','Jorgo Fairwind drinks in Ferdok harbour, near the spot where Ardo was found.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('2d0c0f22-ba16-57ea-b765-5f22849ace5c','Jorgo Fairwind is dead. Their sigil belongs to Master Klingenhand.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_npc_cc_ilgrim','Ilgrim Ashblade');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('c1c34714-6aba-5467-b858-75780714bae4','Smell that? Ash. I burned a chapel of Praios with the priests inside, and the Circle paid me in gold for it. Klingenhand sent you, didn''t he.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('3d86dacd-8c24-58c8-ada1-de797101882e','Your Circle ends here. Draw.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('ca02ffcc-73ab-51dc-a083-a8d4a15e29af','Then let us see if you burn as well as they did!');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('0155cfe9-13de-5ab3-a7c4-6e61104700e8','Not today.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('4f9f20d1-0422-5c22-9db8-e71f69f94cc3','Ilgrim Ashblade');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('baa88ffa-320d-5fb6-b3fc-cbaaf99fc953','Ilgrim Ashblade smells of ash and is fond of ruins. The ledger says no more.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('06b73781-7af9-5344-bf1d-4b8d41e74170','Ilgrim Ashblade is dead. Their sigil belongs to Master Klingenhand.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_npc_cc_faelwen','Faelwen Duskarrow, Hunter of Elves');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('d8d4ffc9-04f7-5595-aed5-9867aa555ead','Quiet, now. I have been listening to you squelch through the marsh for an hour. Elves pay well to have other elves found. Humans pay better to have them lost.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('756b11a3-bac9-5d15-83b4-308de92dd263','Your Circle ends here. Draw.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('393dcdd6-9bb1-5f5e-8963-41aaf7c62531','Run, then. I like it better when they run.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('71fbae11-1a5f-543c-bee8-fbd980a0410a','Not today.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('50326102-fed8-565b-82bd-399208f862c2','Quiet, now. I have been listening to you squelch through the marsh for an hour. Elves pay well to have other elves found. Humans pay better to have them lost.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('b3734c59-44fe-5ac9-a7bf-dbe0e850319b','<Next>');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('0ca469bf-23a3-5c6c-a36f-9e05314a201d','Faelwen. Kin-slayer. The forest still sings the names of those you sold. Today it learns a new verse: yours.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('8f16673b-6309-5263-9845-3ad15a956ea4','Faelwen Duskarrow');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('71a046a1-f8c4-50c6-88af-dd99ccff76a4','Faelwen Duskarrow, an elf who hunts elves, likes old trees and wet feet. He fights with a bow.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('aa792bad-a977-5973-a16f-7d236267aa9a','Faelwen Duskarrow is dead. Their sigil belongs to Master Klingenhand.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_npc_cc_wolfhart','Sir Wolfhart the Oathbreaker');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('311536e9-6ac7-5844-a466-a4dc51413fe1','These dead men served Grimmzahn. So did I, once. I swore on my sword to hold the gate. Then the orcs offered more than the Baron did.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('8b74c689-4eb5-5823-87b9-c1ddcc3c70a8','Your Circle ends here. Draw.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('5519b1df-fe05-5981-9e1d-b4660757c0a2','Klingenhand''s errand-runner. Come, then. I have broken better oaths than you.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('96f7aa14-f874-5294-8de2-28b42b7f120f','Not today.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('cf1e3864-30ec-56df-8c3f-9f8c623601b8','Sir Wolfhart the Oathbreaker');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('3e5b391e-3b13-51ad-b7e8-e0a4520a42a8','Sir Wolfhart the Oathbreaker keeps company with the dead. Sword and shield.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('ae076a3c-f220-54f7-9cd8-6b681f7e8428','Sir Wolfhart the Oathbreaker is dead. Their sigil belongs to Master Klingenhand.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_npc_cc_sabeth','Sabeth Lionsbane, the Outcast');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('dc1cf04c-7c4a-5143-9ec4-9901ce62927f','I hunt the tatzelwurm for its fangs, and the Circle for its gold. Kurkum took my name, my sisters and my lion. It did not take my sword arm.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('7829e015-cb55-5e5d-bd69-61d2b5b6948e','Your Circle ends here. Draw.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('e7aac75f-1ddc-5067-88c9-208168c156c1','Then come, both of you. Rondra loves a good fight.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('05b9a79c-7876-59b4-9a1a-7c0a2bc581f8','Not today.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('b2d022e3-c926-59c8-85c6-872d41073edf','I hunt the tatzelwurm for its fangs, and the Circle for its gold. Kurkum took my name, my sisters and my lion. It did not take my sword arm.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('8cb08757-cef0-5518-a912-02c3bdcf9121','<Next>');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('aad2d3be-2690-551d-bd6f-48f91c870bbe','Sabeth. You killed a sister in a duel of honour and called it justice. Kurkum was merciful to let you leave. Rondra will not be.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('d1f456f0-8aff-5e90-921c-6a8820f9e0e0','Sabeth Lionsbane');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('e1720915-9653-53a8-a75c-f8ba2fe15afd','Sabeth Lionsbane, an outcast Amazon, hunts something with fangs, far from Ferdok.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('70d51531-6a70-5041-8676-3ce7bdfa1247','Sabeth Lionsbane is dead. Their sigil belongs to Master Klingenhand.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_npc_cc_grimbart','Grimbart Ironbeard, the Exile');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('12a6d31d-f8e6-580f-b427-6eddd04f5308','Turn around, longlegs. The Deeps are no place for you. Murolosh cast me out for what I did with this axe, and I have guarded these halls alone ever since.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('2589406e-34d2-5e24-bae5-eb29fe90fdc7','Your Circle ends here. Draw.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('1cff6c1e-1763-5877-935c-c922c3e85c03','A son of Ferolax! Hah! Then I will make it quick, for your father''s sake.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('424e5993-4b94-55a5-aa7a-03f686518fca','Not today.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('74c8bdf7-e8bf-5e6a-962d-c3e5d3d233ae','Turn around, longlegs. The Deeps are no place for you. Murolosh cast me out for what I did with this axe, and I have guarded these halls alone ever since.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('f478e68e-0afb-5b99-80e2-3bc934b4c741','<Next>');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('12b2a29f-a44b-574a-b171-d0df602651b6','Grimbart Ironbeard. My father spoke your name once, then spat in the fire. Pick up your cleaver, exile. Angrosch is watching.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('7e60755b-c0f6-55ce-b7b4-51b9770ef484','Grimbart Ironbeard');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('7ba0cb6b-9f9a-5bea-8aaf-685f56d4f9b2','Grimbart Ironbeard, a banished dwarf, guards something deep under the mountains.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('7ac82842-c647-5922-8686-c50bfee89576','Grimbart Ironbeard is dead. Their sigil belongs to Master Klingenhand.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_npc_cc_ravena','Ravena Blutfeder, the Crimson Master');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('1aabef66-a1df-5f10-9c52-eea6240bde5b','So the old man''s dog has come all this way. You have killed my six best students. I taught every one of them, and I was holding back.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('f0aae582-08e8-5536-a1c0-f048141d7609','Your Circle ends here. Draw.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('035f1d67-be31-5eb4-89db-4538355d7b76','Fire behind me, stone beneath you. Let us finish this.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('5451147f-756e-5746-8e6e-31d422d2ff44','Not today.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('b10e7461-1f2a-5b26-82f4-2e26d1b93407','Ravena Blutfeder, the Crimson Master');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('8f545692-1263-54ac-a082-dd247970e0ac','Ravena Blutfeder, the Crimson Master, waits where fire meets stone.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('487e829c-a569-574b-ac58-c0cc9f551426','Ravena Blutfeder is dead. Their sigil belongs to Master Klingenhand.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_npc_klingenhand','Alrik Klingenhand, Retired Fencing Master');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('4bf25c09-4b92-5b51-a65a-2c917ef91338','Hm? You have a fighter''s hands and a fighter''s eyes. Sit, if you like. Alrik Klingenhand: once the finest blade in Ferdok, now the finest drinker outside the Golden Lance. They keep the bench warm for me.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('c55e080f-192d-5389-820c-3b8659a6cef7','Ah, my young blade. Sit, sit. What news?');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('afd682bf-e150-5d0f-bf81-c7fd932eeb8a','You look like a man with a story.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('abdf2ebb-c4ac-5d76-9c82-9f35e353c61f','A story? Perhaps. Not for someone who has only seen Ferdok, though. Go and see a little of the world, and come back when your boots are muddier.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('a4025973-b4eb-5dbc-afb2-44a4a97dac89','You look like a man with a story.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('9924e4c6-93ca-5ef6-849c-b87b535c4531','Seven students. The best I ever had. They called themselves the Crimson Circle, swore an oath in blood on a red dirk, and sold their swords to anyone who paid. My son challenged them to a friendly bout. It was not friendly. I am too old to hunt them. You are not. Each of them wears a red iron sigil. Bring me all seven, and I will give you what I gave none of them: everything I know.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('36f59736-893e-571a-ba12-5a786a633bcd','I will break the Crimson Circle.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('e30db64f-4f70-57ab-b857-f92b51cecf54','Then take my ledger; it holds all I have heard of them. Start with Jorgo. He drinks in the harbour, where poor Ardo fell. And mind Ravena, the last of them. I taught her everything, and she taught herself the rest.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('0305eb20-27ff-50de-b637-b203fd8b9ae8','Remind me where they are.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('ad937aca-13cd-5e14-a01c-e800f12798a4','Jorgo drinks in the harbour. For the rest I only have scraps: ash and ruins, old trees and wet feet, the company of the dead, fangs far from here, something deep under the mountains, and fire meeting stone. It is all in the ledger. Your road will take you to them, I think. And if I am not here, I will have followed you.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('9845f21f-eab8-553d-a4e7-6fb9b1926d95','I have three of their sigils.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('b2818627-d245-5e1f-9fec-a4c07263dfc4','Three! By Rondra, three. Here: my old fencing gloves. Forty duels and not one lost while I wore them. Keep the sigils; bring me all seven.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('b8f960cd-e393-5ff1-93c0-91c9ba719d0d','All seven sigils. The Circle is broken.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('6c552d4a-d70a-5034-987d-58ddd4973ecc','Seven. Ravena too? Then my son can rest. This ring was mine, when I was the best duelist in the Middenrealm. Wear it. From today, the best is you.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('f0f64e48-dc47-558f-b042-847b54c6e8fa','Sabeth is dead. Rhulana has something to say about her saber.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('250d7927-6780-58d3-90ad-fde8fd42f2ed','Sabeth Lionsbane. She was the best of them, and the saddest. Go on, Amazon. Say it.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('b5bdd4c8-4277-52d2-bf00-089f2c045c59','<Next>');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('93714484-6e7a-5512-8fa2-42a24f063447','She was Kurkum once. Her saber should not be swung by strangers, nor sold. Let me lay it down for her, and Rondra will remember the gift. Or keep it, and make it something greater. It is your choice, not mine.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('9a8fb8c6-23ea-5608-9aac-46a1bee7950f','Lay Lionsbane down for her, Rhulana.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('da69a08a-df21-5d3b-9e70-1718692e7b06','Klingenhand bows his head. Rhulana lays the saber across her mother''s tooth, and when she lifts the tooth again it is bound in braided gold: the Mane of the Lioness, blessed by the dead. Rondra takes her due.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('66d51858-9371-53c1-a829-9bc25eecda0a','We keep it. Sabeth would have wanted it used.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('3f703b4d-6143-5c1e-a6a7-ffd82134ad36','Then use it well. A saber remembers who carried it.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('91276a85-6d24-5261-aba4-56b4276db490','Farewell, Master Klingenhand.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_npc_klingenhand_m','Alrik Klingenhand, Retired Fencing Master');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('ff242eef-75d9-5dc7-bb42-2263d8203327','You found me! I could not sit in Ferdok while you hunted my students across the world. The dwarves serve a fine dark beer. Sit.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('2b1a76a5-7e82-520b-969c-939a2b37e9f3','Ah, my young blade. Sit, sit. What news?');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('508eeb6c-6b67-557c-817a-b95ab56780b6','You look like a man with a story.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('80062125-0171-5349-9ce5-e7cd3e87d9bf','A story? Perhaps. Not for someone who has only seen Ferdok, though. Go and see a little of the world, and come back when your boots are muddier.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('366a9b41-d223-5ece-89aa-5d85237b3a6d','You look like a man with a story.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('710a59a1-2bda-5be3-a655-fe01fb853fba','Seven students. The best I ever had. They called themselves the Crimson Circle, swore an oath in blood on a red dirk, and sold their swords to anyone who paid. My son challenged them to a friendly bout. It was not friendly. I am too old to hunt them. You are not. Each of them wears a red iron sigil. Bring me all seven, and I will give you what I gave none of them: everything I know.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('a7a0ea53-29ec-5f9d-8fed-850fc88555d8','I will break the Crimson Circle.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('e1b6e4a0-a17d-5e89-bf87-7a41566ddc0d','Then take my ledger; it holds all I have heard of them. Start with Jorgo. He drinks in the harbour, where poor Ardo fell. And mind Ravena, the last of them. I taught her everything, and she taught herself the rest.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('a371ee5c-eddb-5598-b526-1f7469a993f4','Remind me where they are.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('543dbf70-7e9c-599a-99a5-fa5ce0e86aff','Jorgo drinks in the harbour. For the rest I only have scraps: ash and ruins, old trees and wet feet, the company of the dead, fangs far from here, something deep under the mountains, and fire meeting stone. It is all in the ledger. Your road will take you to them, I think. And if I am not here, I will have followed you.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('8b152419-33e9-5ffd-8648-baf1e58de938','I have three of their sigils.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('0e854dc1-385a-5763-a42d-b45eb12a587d','Three! By Rondra, three. Here: my old fencing gloves. Forty duels and not one lost while I wore them. Keep the sigils; bring me all seven.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('a08ec85c-0e54-5def-a556-bdd56dff72c3','All seven sigils. The Circle is broken.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('52e59b55-2627-5173-9a41-73c571bf8a1b','Seven. Ravena too? Then my son can rest. This ring was mine, when I was the best duelist in the Middenrealm. Wear it. From today, the best is you.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('fe42bc45-1e2e-57c8-914f-1e82be8c454a','Sabeth is dead. Rhulana has something to say about her saber.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('d1a35455-d888-5e66-9289-aff78002aac6','Sabeth Lionsbane. She was the best of them, and the saddest. Go on, Amazon. Say it.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('9837a826-e457-538a-ac19-07ae3eec770a','<Next>');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('1ac418f5-ab18-5604-94de-9378790f163f','She was Kurkum once. Her saber should not be swung by strangers, nor sold. Let me lay it down for her, and Rondra will remember the gift. Or keep it, and make it something greater. It is your choice, not mine.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('e4f99a8e-3f97-5195-b9a7-c500d700bab9','Lay Lionsbane down for her, Rhulana.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('2e5501b5-4cfe-5039-b53c-45dba4f90b80','Klingenhand bows his head. Rhulana lays the saber across her mother''s tooth, and when she lifts the tooth again it is bound in braided gold: the Mane of the Lioness, blessed by the dead. Rondra takes her due.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('05f59f17-71c0-54f8-9066-98ef47703d90','We keep it. Sabeth would have wanted it used.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('2b2c801f-50f7-59e8-9ff2-b94a3ff84cab','Then use it well. A saber remembers who carried it.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('fb4e4966-2069-5e25-ba53-1aa07daacd95','Farewell, Master Klingenhand.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('77534bfe-e04b-5577-860c-be79c0103ba9','The Crimson Circle');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('7066130e-28ca-5614-ad95-2b55cdb6d0c7','Master Alrik Klingenhand, outside the Golden Lance in Ferdok, asked me to hunt down the seven duelists of the Crimson Circle and bring him their sigils. His ledger has a hint for each. He says he may follow me if my road goes far.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('9141cb3f-ec2e-5b91-9dcc-21b4f675f6c1','The Crimson Circle is broken. Master Klingenhand gave me his ring.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('dbcae329-8246-57ff-a8d3-10a9def91b2f','Seven Sigils');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('19050da5-b6dc-587c-a560-e1a8bf8ea74f','All seven duelists are dead. Bring their sigils to Master Klingenhand, outside the Golden Lance or wherever he has followed me.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('e0534352-bcfb-536f-9021-6f560f6a066c','I gave Master Klingenhand all seven sigils.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_npc_rk_echo','Echo of the Codex');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('26cdc605-31e4-5261-92bf-a5aa3483898f','Codex Page I: Of Embers');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('10b16423-3a5d-5a36-96e2-72eaf9ffb9a2','Find the page in the sewers under Ferdok.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('fb9c9466-8ec7-5c3e-9a4c-6ffb2567b5c8','I brought "Codex Page I: Of Embers" to Rakorium.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('8ce30120-6a57-5ecd-bcda-050bae77e354','Codex Page II: Of Ashes');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('3e00a638-1c3b-5c9d-9548-c94ded6de0e9','Find the page where robbers hoard what they steal.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('992e3dc3-8377-5f6b-adfe-84da464891b2','I brought "Codex Page II: Of Ashes" to Rakorium.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('aeeb9a29-fcd4-5e54-9ad2-205f35278d11','Codex Page III: Of Bones');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('4a29d22c-87f3-534f-8cc7-cb7925f5b926','Find the page where the dead are buried with their secrets.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('cca920f1-6b4d-52c4-a8d7-e626f4221eea','I brought "Codex Page III: Of Bones" to Rakorium.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('2e9ec720-5c27-55ad-9cad-e4f6287f7e62','Codex Page IV: Of Dreams');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('f192b92b-7e11-5260-9160-d9a0db4f14a4','Find the page in the vaults of an old castle.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('75d5be0f-5a89-5be7-bf14-5c315c1396d0','I brought "Codex Page IV: Of Dreams" to Rakorium.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('1d3925ce-e39d-5372-99b3-0a9d09a58e4b','Master Rakorium, is there anything I could do for your research?');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('483ed358-0878-555c-a36b-690c2c8df296','Research? Research! Yes! The Codex Pyrdaconis, the dream-book of the great dragon Pyrdacor himself, torn into four pages by a careless Hesindian novice and scattered to the winds. One went down the sewers right here in Ferdok, I am sure of it. The others? Wherever robbers, the dead and old stone walls keep things. You go everywhere, don''t you? Bring them to me and I will prove, once and for all, that dragons dream. In verse!');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('7c81ea6d-00b9-521f-a874-2741131a4431','I will find your four pages, Master.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('063dbaba-9487-57b2-bf5d-e0c9331be450','Splendid! Sewers, robbers, crypts, vaults. All the nice places. Bring each page as you find it; every chapter makes the next one easier to read.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('835f1501-0bb6-566c-a498-6a2cd119e555','Perhaps another time.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('650166d7-6d16-5e0a-baea-2c3f80b5259f','Another time, another time. Everything is another time with you young people.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('4dfd1d62-bab8-5fd4-ae75-499ff684821b','I found a page of your codex: "Of Embers".');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('8294be8c-c840-5983-b008-70bf2b9af8bb','Of Embers! Ha! The first chapter! Look at this, look: the dragon''s breath is a sentence, and the fire is only its punctuation. Here, take some scrolls. I wrote them myself. Mostly.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('171faaff-1ea6-5b31-aa65-0472ec441237','I found a page of your codex: "Of Ashes".');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('1fb2f382-ecbb-5550-959b-445af8c09d59','Of Ashes! Burned, and yet the ink survived. That is not ink. Never mind what it is. Take this wand; I was using it to keep my tea cold. It is called the Wand of Rime.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('7c177dee-42bd-5a4c-985f-787e9cb5abf3','I found a page of your codex: "Of Bones".');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('cae7be64-9b68-5f6d-8a8a-53fd66a820a6','Of Bones! Moorbridge, of course, where else would bones keep secrets. You have earned my spare spectacles. Through them, magic looks like handwriting. Do not read your own.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('32818f73-9871-516f-b667-f04ac0572c08','I found a page of your codex: "Of Dreams".');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('36a29e3d-d788-5527-9f75-f0a62db35307','Of Dreams! Grimmzahn''s vaults! The orcs used it as a napkin, the barbarians. Some gold for your trouble, and two more scrolls. Now we only need to read it aloud...');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('6df40ca6-08dd-5c98-99a2-c92c98148991','You have all four pages now, Master. What happens next?');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('18bcb9d1-d83f-53a4-8f4f-fa36c91383b2','Next? Next, we read it. Aloud. The proof only works aloud, it is a poem, you see. Ahem. ''In the dreaming of the Wyrm, the ink awakes, and what was written writes itself anew...'' Hm. Is it warm in here? Is the page supposed to glow like that?');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('6dd87e73-76ec-5f70-aa09-26550331543b','Master Rakorium, something is coming out of the pages!');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('3df424f9-2b8c-5892-8c80-de76b14b52c2','Oh. Oh dear. That is an Echo: the codex wrote its own reader. Proof that dragons dream! Proof that they have nightmares, too! Here, take my robe, the one I win arguments in, and my hat, my BEST hat, and hit it until it stops! I shall supervise from behind this chair!');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('78b079a3-fa2e-5ca8-b561-4eba182dc540','The Codex of Hidden Fire');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('9e7972d3-8969-568d-9973-d28cbe1bf552','Master Rakorium wants the four lost pages of the Codex Pyrdaconis, the dream-book of the dragon Pyrdacor.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('3b841b3c-901c-52b8-95a2-88d8a5f28d22','Rakorium read the codex aloud. Dragons dream, and their dreams bite.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('97261b7a-1f46-5b6b-8b5a-af5f95992f95','The Proof');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('9cb405d3-34d3-585a-9e62-3389bc5de943','All four pages are with Rakorium. He wants to read the codex aloud.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('a865256d-b953-5d9e-a487-e4aee576993b','Rakorium read the codex. Something answered.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_npc_wendelin','Wendelin Raunefuss, Teller of Rumours');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('77d6a1cc-a3c3-526a-860b-9444afeb81e7','Psst. Over here. Wendelin Raunefuss, collector of rumours, whispers and half-truths. For you, the first ones are free. They are all free, actually. Nobody ever pays.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('d9e4721b-b392-55c9-874a-c18adc418182','Back for more whispers? I have plenty.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('689f8a96-ed22-505a-8200-217acea9b30a','Heard anything about skilled fighters?');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('c48099c4-e00a-58e6-be55-21523724931f','Old Alrik Klingenhand drinks alone on the bench outside the Golden Lance. They say he trained the Crimson Circle: seven duelists who sell their swords. Ask him what happened to his son.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('22e4fbea-6caf-53f7-87e5-a9f17c35ddf8','Anything about magic?');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('ffc116b3-10b9-5f78-a742-5bb52f5c6491','Your house guest, Master Rakorium, mutters about torn pages of a dragon''s codex. Ask him if there is anything you can do for his research. Mind you, one page went down the sewers, and nobody sane goes down there.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('75deb5a4-60d6-50b5-97a7-1c5bc908adee','And outside Ferdok?');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('f511f1df-7b11-5f0c-bb3d-fc3b5f004e9e','A trophy collector, Ulfried, trades on Praios Square by the bowyer, and follows the hunters wherever the game gets bigger. Pays in silver and jewellery for fangs and claws. And the chickens of Avestrue. Skin one. Trust me. Oh, and if you ever find a talking hat, do not listen to it.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('7681c3ee-e0e0-5cb8-8b9e-2b4f11b08720','Anything my Amazon friend should hear?');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('4c87fdb9-6c5a-50af-bfb5-2c94091fb4e9','An outcast Amazon, Sabeth Lionsbane, sells her sword to the Crimson Circle now. She carries a saber that belongs in Kurkum. If your road goes far enough, it will cross hers.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('ce901206-960f-5fb9-a2a7-0a03eb52bf2e','Anything about elves?');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('58fa9f32-b074-5d44-ba85-062b70125ec1','There is an elf who hunts elves for gold. Faelwen Duskarrow. He likes old trees and wet ground, and his bow sings.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('365bca2a-ca9d-51b4-8c1e-534cfb4b456f','Anything about dwarves?');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('68a90116-54cf-5ae2-99de-426c0028cdda','A banished dwarf, Grimbart Ironbeard, guards something deep under the mountains. Dwarves do not say his name.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('48993da6-3fc6-5b04-b170-154614269b56','Any treasure worth the trouble?');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('33a6678b-0570-5d83-bb88-a77a4e5705a9','Treasure? Dragons sleep on it, they say, and dwarves bury it so deep they forget where. Burned castles hide more than ash. And the dead keep diaries: read them. Where? If I knew, would I be standing in Wagoner''s Home?');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('2b1490be-6f7e-542f-acc7-ab0579341a24','Thanks, Wendelin.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('ebfbfd44-ac58-59e6-be4e-cacd4e6a6baa','How is Holdwin doing?');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('1e00f1da-7ea5-5661-a09a-b4b03d2ea6b0','Up and grumbling, thanks to you. Here, take Holdwin''s old maul. He says his back is done with it, and you look like you have more bandits ahead of you than he has logs. It splits both.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('bd69d81e-ddfe-5f90-b4e0-3b527023fc84','Can you temper what I carry, master smith?');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('d1eec2fc-f0a1-533e-8267-698d03ffbc82','Temper it? Hrm. The Last Fire burns hot enough, but fire alone is not enough. Bring a scale of the Purplewyrm and good dwarven steel, and follow these marks at any forge. The blade will remember this flame for a thousand years.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('e6b8aa45-866b-55b5-9691-c9129c1a4ffb','Can you temper what I carry, master smith?');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('a6b6225b-677e-5580-9615-586f31325e3b','Temper it? Hrm. The Last Fire burns hot enough, but fire alone is not enough. Bring a scale of the Purplewyrm and good dwarven steel, and follow these marks at any forge. The blade will remember this flame for a thousand years.');
