INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_mo_greymaw','The alpha of the mad pack. Grey as iron, and it does not flinch from fire.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookatdead_arm_mo_greymaw','Dead Greymaw, the Mad Alpha');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_mo_greymaw','Greymaw, the Mad Alpha');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_mo_stormhowl','A white wolf whose fur crackles like a coming storm. Lightning answers when it is struck.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookatdead_arm_mo_stormhowl','Dead Stormhowl');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_mo_stormhowl','Stormhowl');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_mo_madwolf_01','A wolf with silver in its eyes. It does not run.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookatdead_arm_mo_madwolf_01','Dead Moon-mad Wolf');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_mo_madwolf_01','Moon-mad Wolf');
