INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_npc_hagen','Hagen, Goatherd');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('eeb20c9c-039e-5a0a-9455-f5e1a173397e','You there, with the weapons! You look like you know which end to hold. Good. Somebody has to do something about the wolves.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('951b7c50-4ca4-541c-8fd0-0d7614d72b74','Any news from the western woods? I still hear them at night.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('f6f022be-7ebb-5738-8bfb-cbe903475303','What about the wolves?');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('75e72889-f735-51ec-a57d-91133d3a45e5','Alvina''s wolves. The witch who walks the woods keeps them the way I keep goats. This spring a storm came down on the western woods, and something came with it. Now her wolves hunt as one pack, fifteen of them, eyes like coals, and they do not run from fire. A big grey alpha leads them; we call him Greymaw. And with them runs a white one whose fur crackles like lightning. Stormhowl. My goats are gone. My dog is gone. Next it will be a child. Kill the two leaders and the madness dies with them. I can pay, and I know what those pelts are good for.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('486efbbc-f067-5ecf-8286-ea2e0edb1d4d','I will hunt the mad pack.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('68ca2410-02cf-592e-ac82-32b5f4bc2a0d','West, where the trees grow close and the old road gives up. Do not go tired and do not go alone. They hunt together, so should you.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('43e91189-bdec-5693-95a2-dc26d0ee6868','Greymaw and Stormhowl are dead.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('99297809-b597-5028-800f-f21b4675e704','I heard the howling stop last night and did not dare believe it. Thank you. Here: my grandmother was a trapper, and these are her notes. Moon-mad pelt and sinew make leather no blade likes to bite and a bowstring that sings. Take them to any workbench. And the purse. It is not much, but the goats would want you to have it.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('722c3d3e-ac48-551b-a6e4-9ac989fc4da5','Farewell, Hagen.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('439d034b-5705-5e05-94f0-503352c0f78e','The Mad Pack');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('bbc6d8b9-46df-56ab-9aa4-32dff7c09ec5','Hagen, a goatherd in the Dark Forest, says Alvina''s wolves have gone mad and hunt as one pack in the western woods. He wants their leaders dead: the grey alpha Greymaw and the white wolf Stormhowl.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('5a0a4306-9c91-5010-8ae2-ff5c72b526ac','The mad pack is dead. Hagen gave me his grandmother''s trapper notes.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('442a63a2-4ee3-579c-b555-8fcce22ce371','Greymaw and Stormhowl');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('8e4458ec-264a-5871-a1af-1233cf045f81','Kill the two leaders of the mad pack in the western woods. The rest of the pack will not stand aside.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('5f7b2c68-7362-57f0-9fc4-365a9ecd29c7','Greymaw and Stormhowl are dead.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('58ee9ae1-938d-57a0-b44e-da996b7ae8e9','Back to Hagen');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('80a0afbb-753d-5a82-bd6f-17c31f5a0a16','Tell Hagen the goatherd that the pack is broken.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('4456fa9a-6749-5447-b3ec-2f4e7cc1773a','I told Hagen.');
